          ]
        },
        {
          "id": "title",
          "component": "Text",
          "variant": "h1",
          "text": "Rome 2-Day Walking Itinerary: Pantheon Base"
        },
        {
          "id": "assumptions_header",
          "component": "Text",
          "variant": "h2",
          "text": "Assumptions"
        },
        {
          "id": "assumptions_list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "assumption_1",
            "assumption_2",
            "assumption_3",
            "assumption_4"
          ]
        },
        {
          "id": "assumption_1",
          "component": "Text",
          "text": "- You have a moderate fitness level and are comfortable with significant walking (15,000-25,000 steps per day)."
        },
        {
          "id": "assumption_2",
          "component": "Text",
          "text": "- All major attraction tickets will be pre-booked online to guarantee entry and skip long ticket lines. This is essential."
        },
        {
          "id": "assumption_3",
          "component": "Text",
          "text": "- The budget of 100 Euros per person per day is for food and scheduled entry fees only, not including souvenirs, extra transport, or shopping."
        },
        {
          "id": "assumption_4",
          "component": "Text",
          "text": "- Prices for tickets and food are estimates for 2024 and should be verified."
        },
        {
          "id": "checklist_header",
          "component": "Text",
          "variant": "h2",
          "text": "Pre-Trip Checklist"
        },
        {
          "id": "checklist_list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "check_1",
            "check_2",
            "check_3",
            "check_4",
            "check_5"
          ]
        },
        {
          "id": "check_1",
          "component": "Text",
          "text": "- Book Colosseum & Roman Forum ticket online for Day 1 (9:00 AM slot)."
        },
        {
          "id": "check_2",
          "component": "Text",
          "text": "- Book Vatican Museums & Sistine Chapel ticket online for Day 2 (8:30 AM slot)."
        },
        {
          "id": "check_3",
          "component": "Text",
          "text": "- Purchase the new Pantheon entry ticket online or plan to queue."
        },
        {
          "id": "check_4",
          "component": "Text",
          "text": "- Download an offline map of Rome (e.g., Google Maps offline feature)."
        },
        {
          "id": "check_5",
          "component": "Text",
          "text": "- Pack comfortable walking shoes. This is the most important item."
        },
        {
          "id": "budget_header",
          "component": "Text",
          "variant": "h2",
          "text": "Budget & Ticket Framework"
        },
        {
          "id": "budget_intro",
          "component": "Text",
          "text": "This is an example breakdown of your daily 100 Euro budget."
        },
        {
          "id": "budget_table",
          "component": "List",
          "direction": "vertical",
          "children": [
            "budget_table_header_row",
            "budget_table_row_1",
            "budget_table_row_2",
            "budget_table_row_3",
            "budget_table_row_4",
            "budget_table_row_5",
            "budget_table_row_total"
          ]
        },
        {
          "id": "budget_table_header_row",
          "component": "Row",
          "children": [
            "budget_header_cat",
            "budget_header_cost",
            "budget_header_notes"
          ]
        },
        {
          "id": "budget_header_cat",
          "component": "Text",
          "text": "**Category**",
          "weight": 1
        },
        {
          "id": "budget_header_cost",
          "component": "Text",
          "text": "**Estimated Cost**",
          "weight": 1
        },
        {
          "id": "budget_header_notes",
          "component": "Text",
          "text": "**Notes**",
          "weight": 2
        },
        {
          "id": "budget_table_row_1",
          "component": "Row",
          "children": [
            "budget_cat_1",
            "budget_cost_1",
            "budget_notes_1"
          ]
        },
        {
          "id": "budget_cat_1",
          "component": "Text",
          "text": "Entry Fees (Avg.)",
          "weight": 1
        },
        {
          "id": "budget_cost_1",
          "component": "Text",
          "text": "€25",
          "weight": 1
        },
        {
          "id": "budget_notes_1",
          "component": "Text",
          "text": "Colosseum (~€20), Vatican (~€25), Pantheon (€5). Averaged over 2 days.",
          "weight": 2
        },
        {
          "id": "budget_table_row_2",
          "component": "Row",
          "children": [
            "budget_cat_2",
            "budget_cost_2",
            "budget_notes_2"
          ]
        },
        {
          "id": "budget_cat_2",
          "component": "Text",
          "text": "Breakfast",
          "weight": 1
        },
        {
          "id": "budget_cost_2",
          "component": "Text",
          "text": "€5",
          "weight": 1
        },
        {
          "id": "budget_notes_2",
          "component": "Text",
          "text": "Cappuccino and a cornetto at a local bar (standing at the counter is cheaper).",
          "weight": 2
        },
        {
          "id": "budget_table_row_3",
          "component": "Row",
          "children": [
            "budget_cat_3",
            "budget_cost_3",
            "budget_notes_3"
          ]
        },
        {
          "id": "budget_cat_3",
          "component": "Text",
          "text": "Lunch",
          "weight": 1
        },
        {
          "id": "budget_cost_3",
          "component": "Text",
          "text": "€15",
          "weight": 1
        },
        {
          "id": "budget_notes_3",
          "component": "Text",
          "text": "Pizza al taglio (by the slice) or a fresh panino.",
          "weight": 2
        },
        {
          "id": "budget_table_row_4",
          "component": "Row",
          "children": [
            "budget_cat_4",
            "budget_cost_4",
            "budget_notes_4"
          ]
        },
        {
          "id": "budget_cat_4",
          "component": "Text",
          "text": "Dinner",
          "weight": 1
        },
        {
          "id": "budget_cost_4",
          "component": "Text",
          "text": "€40",
          "weight": 1
        },
        {
          "id": "budget_notes_4",
          "component": "Text",
          "text": "A sit-down meal at a trattoria (pasta/pizza, glass of house wine, water).",
          "weight": 2
        },
        {
          "id": "budget_table_row_5",
          "component": "Row",
          "children": [
            "budget_cat_5",
            "budget_cost_5",
            "budget_notes_5"
          ]
        },
        {
          "id": "budget_cat_5",
          "component": "Text",
          "text": "Snacks/Gelato",
          "weight": 1
        },
        {
          "id": "budget_cost_5",
          "component": "Text",
          "text": "€15",
          "weight": 1
        },
        {
          "id": "budget_notes_5",
          "component": "Text",
          "text": "Includes water, coffee breaks, and essential daily gelato.",
          "weight": 2
        },
        {
          "id": "budget_table_row_total",
          "component": "Row",
          "children": [
            "budget_cat_total",
            "budget_cost_total",
            "budget_notes_total"
          ]
        },
        {
          "id": "budget_cat_total",
          "component": "Text",
          "text": "**Total**",
          "weight": 1
        },
        {
          "id": "budget_cost_total",
          "component": "Text",
          "text": "**€100**",
          "weight": 1
        },
        {
          "id": "budget_notes_total",
          "component": "Text",
          "text": "",
          "weight": 2
        },
        {
          "id": "verify_header",
          "component": "Text",
          "variant": "h3",
          "text": "How to Verify Ticket Prices & Book:"
        },
        {
          "id": "verify_list",
          "component": "List",
          "direction": "vertical",
          "children": [
            "verify_1",
            "verify_2",
            "verify_3",
            "verify_4"
          ]
        },
        {
          "id": "verify_1",
          "component": "Text",
          "text": "1. Visit the official websites provided in the 'Sources' section below."
        },
        {
          "id": "verify_2",
          "component": "Text",
          "text": "2. Select your desired date (2024-09-15 for Colosseum, 2024-09-16 for Vatican)."
        },
        {
          "id": "verify_3",
          "component": "Text",
          "text": "3. Choose your time slot. Morning slots are highly recommended."
        },
        {
          "id": "verify_4",
          "component": "Text",
          "text": "4. Complete the purchase and save the digital ticket to your phone."
        },
        {
          "id": "quick_actions_row",
          "component": "Row",
          "justify": "start",
          "children": [
            "colosseum_button",
            "vatican_button"
          ]
        },
        {
          "id": "colosseum_button",
          "component": "Button",
          "variant": "primary",
          "child": "colosseum_button_text",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://coopculture.it"
              }
            }
          }
        },
        {
          "id": "colosseum_button_text",
          "component": "Text",
          "text": "Book Colosseum Tickets"
        },
        {
          "id": "vatican_button",
          "component": "Button",
          "variant": "primary",
          "child": "vatican_button_text",
          "action": {
            "functionCall": {
              "call": "openUrl",
              "args": {
                "url": "https://museivaticani.va"
              }
            }
          }
        },
        {
          "id": "vatican_button_text",
          "component": "Text",
          "text": "Book Vatican Museums Tickets"
        },
        {
          "id": "divider_1",
          "component": "Divider"
        },
        {
          "id": "day1_header",
          "component": "Text",
          "variant": "h2",
          "text": "Itinerary Day 1 (2024-09-15): Ancient Rome"
        },
        {
          "id": "day1_focus",
          "component": "Text",
          "text": "Focus: Immerse yourself in the heart of the Roman Empire."
        },
        {
          "id": "day1_morning_header",
          "component": "Text",
          "variant": "h3",
          "text": "MORNING (8:00 AM - 1:00 PM)"
        },
        {
          "id": "day1_morning_content",
          "component": "Column",
          "children": [
            "day1_morning_item1",
            "day1_morning_item2",
            "day1_morning_item3"
          ]
        },
        {
          "id": "day1_morning_item1",
          "component": "Row",
          "align": "start",
          "children": [
            "sightseeing_icon_1",
            "day1_morning_item1_text"
          ]
        },
        {
          "id": "sightseeing_icon_1",
          "component": "Image",
          "url": "https://icon.url/sightseeing",
          "variant": "icon"
        },
        {
          "id": "day1_morning_item1_text",
          "component": "Column",
          "weight": 1,
          "children": [
            "day1_morning_item1_desc",
            "day1_morning_item1_walk"
          ]
        },
        {
          "id": "day1_morning_item1_desc",
          "component": "Text",
          "text": "8:00 AM: Start from your lodging near the Pantheon. Walk towards Piazza Venezia to see the Altare della Patria (Vittoriano). You can view it from the outside to save time and money."
        },
        {
          "id": "day1_morning_item1_walk",
          "component": "Row",
          "align": "start",
          "children": [
            "walking_icon_1",
            "day1_morning_item1_walk_text"
          ]
        },
        {
          "id": "walking_icon_1",
          "component": "Image",
          "url": "https://icon.url/walking",
          "variant": "icon"
        },
        {
          "id": "day1_morning_item1_walk_text",
          "component": "Text",
          "text": "Pantheon to Piazza Venezia: Approx. 10 minutes.",
          "weight": 1
        },
        {
          "id": "day1_morning_item2",
          "component": "Row",
          "align": "start",
          "children": [
            "sightseeing_icon_2",
            "day1_morning_item2_text"
          ]
        },
        {
          "id": "sightseeing_icon_2",
          "component": "Image",
          "url": "https://icon.url/sightseeing",
          "variant": "icon"
        },
        {
          "id": "day1_morning_item2_text",
          "component": "Text",
          "text": "8:30 AM: Walk along Via dei Fori Imperiali towards the Colosseum. This road is flanked by the ruins of ancient forums.",
          "weight": 1
        },
        {
          "id": "day1_morning_item3",
          "component": "Row",
          "align": "start",
          "children": [
            "sightseeing_icon_3",
            "day1_morning_item3_text"
          ]
        },
        {
          "id": "sightseeing_icon_3",
          "component": "Image",
          "url": "https://icon.url/sightseeing",
          "variant": "icon"
        },
        {
          "id": "day1_morning_item3_text",
          "component": "Column",
          "weight": 1,
          "children": [
            "day1_morning_item3_desc",
            "day1_morning_item3_tip",
            "day1_morning_item3_details",
            "day1_morning_item3_walk"
          ]
        },
        {
          "id": "day1_morning_item3_desc",
          "component": "Text",
          "text": "9:00 AM - 12:00 PM: **Colosseum, Roman Forum & Palatine Hill**."
        },
        {
          "id": "day1_morning_item3_tip",
          "component": "Row",
          "align": "start",
          "children": [
            "tip_icon_1",
            "day1_morning_item3_tip_text"
          ]
        },
        {
          "id": "tip_icon_1",
          "component": "Image",
          "url": "https://icon.url/tip",
          "variant": "icon"
        },
        {
          "id": "day1_morning_item3_tip_text",
          "component": "Text",
          "text": "Use your pre-booked 9:00 AM ticket for the Colosseum. The visit takes about 1.5 hours.",
          "weight": 1
        },
        {
          "id": "day1_morning_item3_details",
          "component": "Text",
          "text": "After the Colosseum, your ticket gives you access to the adjacent Roman Forum and Palatine Hill. Allow at least 1.5 hours to explore these vast ruins. Start with Palatine Hill for great views over the Forum."
        },
        {
          "id": "day1_morning_item3_walk",
          "component": "Row",
          "align": "start",
          "children": [
            "walking_icon_2",
            "day1_morning_item3_walk_text"
          ]
        },
        {
          "id": "walking_icon_2",
          "component": "Image",
          "url": "https://icon.url/walking",
          "variant": "icon"
        },
        {
          "id": "day1_morning_item3_walk_text",
          "component": "Text",
          "text": "Piazza Venezia to Colosseum: Approx. 15 minutes.",
          "weight": 1
        },
        {
          "id": "day1_lunch_header",
          "component": "Text",
          "variant": "h3",
          "text": "LUNCH (1:00 PM - 2:00 PM)"
        },
        {
          "id": "day1_lunch_content",
          "component": "Row",
          "align": "start",
          "children": [
            "food_icon_1",
            "day1_lunch_text"
          ]
        },
        {
          "id": "food_icon_1",
          "component": "Image",
          "url": "https://icon.url/food",
          "variant": "icon"
        },
        {
          "id": "day1_lunch_text",
          "component": "Text",
          "text": "Avoid the restaurants directly facing the Colosseum. Walk a few blocks away towards the Monti or Celio neighborhoods for better value and quality.",
          "weight": 1
        },
        {
          "id": "day1_lunch_options_row",
          "component": "Row",
          "children": [
            "day1_lunch_card1",
            "day1_lunch_card2",
            "day1_lunch_card3"
          ]
        },
        {
          "id": "day1_lunch_card1",
          "component": "Card",
          "weight": 1,
          "child": "day1_lunch_card1_content"
        },
        {
          "id": "day1_lunch_card1_content",
          "component": "Column",
          "children": [
            "day1_lunch_card1_title",
            "day1_lunch_card1_name",
            "day1_lunch_card1_desc",
            "day1_lunch_card1_price"
          ]
        },
        {
          "id": "day1_lunch_card1_title",
          "component": "Text",
          "text": "**Option 1: Pizza al Taglio**"
        },
        {
          "id": "day1_lunch_card1_name",
          "component": "Text",
          "text": "Forno da Milvio",
          "variant": "caption"
        },
        {
          "id": "day1_lunch_card1_desc",
          "component": "Text",
          "text": "Grab delicious, affordable pizza by the slice."
        },
        {
          "id": "day1_lunch_card1_price",
          "component": "Text",
          "text": "€10-€15"
        },
        {
          "id": "day1_lunch_card2",
          "component": "Card",
          "weight": 1,
          "child": "day1_lunch_card2_content"
        },
        {
          "id": "day1_lunch_card2_content",
          "component": "Column",
          "children": [
            "day1_lunch_card2_title",
            "day1_lunch_card2_name",
            "day1_lunch_card2_desc",
            "day1_lunch_card2_price"
          ]
        },
        {
          "id": "day1_lunch_card2_title",
          "component": "Text",
          "text": "**Option 2: Quick Panini**"
        },
        {
          "id": "day1_lunch_card2_name",
          "component": "Text",
          "text": "La Prezzemolina",
          "variant": "caption"
        },
        {
          "id": "day1_lunch_card2_desc",
          "component": "Text",
          "text": "Fresh, made-to-order sandwiches perfect for a fast and tasty lunch."
        },
        {
          "id": "day1_lunch_card2_price",
          "component": "Text",
          "text": "€8-€12"
        },
        {
          "id": "day1_lunch_card3",
          "component": "Card",
